insert into platform_modules(code,title,is_active) values ('38-navigation-rules','قواعد نمایش و ناوبری فرانت‌اند',true) on conflict(code) do update set title=excluded.title,is_active=true;
insert into module_field_definitions(module_id,field_key,title,field_type,required,sort_order,options)
insert into module_actions(module_id,action_code,title,permission) select m.id,v.a,v.t,v.p from platform_modules m cross join (values
('read','مشاهده قواعد','modules:38-navigation-rules:read'),('write','ساخت و ویرایش قاعده','modules:38-navigation-rules:write'),('delete','حذف قاعده','modules:38-navigation-rules:delete'),('publish','فعال‌سازی قاعده','modules:38-navigation-rules:publish'),('disable','غیرفعال‌سازی قاعده','modules:38-navigation-rules:disable'),('duplicate','تکثیر قاعده','modules:38-navigation-rules:duplicate'),('reorder','تنظیم اولویت','modules:38-navigation-rules:reorder')) v(a,t,p) where m.code='38-navigation-rules' on conflict(module_id,action_code) do update set title=excluded.title,permission=excluded.permission;