select m.id,v.k,v.t,v.ft,v.r,v.s,v.o::jsonb from platform_modules m cross join (values
('rule-code','کد قاعده','text',true,10,'{}'),('rule-title','عنوان قاعده','text',true,20,'{}'),('menu-code','کد منو','text',true,30,'{}'),('page-code','کد صفحه','text',false,40,'{}'),('section-code','کد بخش','text',false,50,'{}'),('audience','مخاطب','select',true,60,'{"options":["عمومی","کاربران واردشده","کاربران مهمان","نقش‌محور","سازمانی"]}'),('condition-type','نوع شرط','select',true,70,'{"options":["بدون شرط","مجوز","نقش","سازمان","وضعیت کاربر","ترکیبی"]}'),('condition-reference','مرجع شرط','text',false,80,'{}'),('priority','اولویت','number',true,90,'{}'),('display-mode','نحوه نمایش','select',true,100,'{"options":["نمایش","مخفی","نمایش مشروط","فقط موبایل","فقط دسکتاپ"]}'),('target-mode','نحوه بازشدن','select',true,110,'{"options":["همان صفحه","صفحه جدید","پنجره داخلی","مسیر خارجی"]}'),('status','وضعیت','select',true,120,'{"options":["پیش‌نویس","فعال","غیرفعال","آرشیو شده"]}'),('effective-from','شروع اعتبار','text',false,130,'{}'),('effective-to','پایان اعتبار','text',false,140,'{}'),('notes','یادداشت','textarea',false,150,'{}')
) v(k,t,ft,r,s,o) where m.code='38-navigation-rules' on conflict(module_id,field_key) do update set title=excluded.title,field_type=excluded.field_type,required=excluded.required,sort_order=excluded.sort_order,options=excluded.options;
